// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize with a non-zero baseToken (e.g., address(this) as baseToken)
        c.initialize(
            address(this),   // _baseToken: non-zero
            address(this),   // _nft: arbitrary
            1e18,            // _virtualBaseTokenReserves
            1e18,            // _virtualNftReserves
            1,               // _changeFee
            500,             // _feeRate (<= 5000)
            bytes32(0),      // _merkleRoot
            false,           // _useStolenNftOracle
            false            // _payRoyalties
        );

        // Mint an NFT to the contract so availableForFlashLoan returns true
        // (We use the same address for nft, so we need to simulate an ERC721 owner check)
        // But for the flashLoan we need the contract to own tokenId. Let's mint via internal _mint:
        // Since C is abstract, we can't call _mint directly. Instead we'll use a concrete approach:
        // The test deploys C with constructor args; we can use the fact that the contract owns nothing.
        // For a flashLoan, availableForFlashLoan requires ERC721(token).ownerOf(tokenId) == address(this).
        // We'll just test availableForFlashLoan directly as the difference point.

        // The difference: baseToken is address(0) in bug, address(this) in correct.
        // So we call a view that reads baseToken.
        bool isBaseTokenZero = (c.baseToken() == address(0));
        assertTrue(isBaseTokenZero); // This assertion passes for the bug (baseToken == 0) and fails for the reference (baseToken != 0)
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize with a non-zero baseToken (e.g., a mock ERC20)
        address mockBaseToken = address(0x1234);
        c.initialize(mockBaseToken, address(this), 1e18, 1e18, 0, 0, bytes32(0), false, false);

        // Call flashFee - for reference: returns value based on mockBaseToken.decimals()
        // For bug: returns value based on address(0).decimals() which reverts
        bool ok;
        try c.flashFee(address(0), 0) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference succeeds (returns a fee), bug reverts (no getter on address(0))
        assertTrue(ok);
    }
}

