pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize the contract so it can be used
        c.initialize(
            address(0),                  // baseToken (ETH)
            address(this),               // nft (dummy, won't mint)
            1000 ether,                  // virtualBaseTokenReserves
            10 ether,                    // virtualNftReserves
            100,                         // changeFee
            0,                           // feeRate (will change later)
            bytes32(0),                  // merkleRoot (no merkle)
            false,                       // useStolenNftOracle
            false                        // payRoyalties
        );

        // Mint a dummy NFT to address(this) so we can use it
        // We simulate by transferring ownership via availableForFlashLoan
        // but the NFT must be owned by the pool. We'll deploy an ERC721-like token.
        // Simpler: use address(1) as the NFT address and rely on availableForFlashLoan reverting
        // because token ID 1 is not minted. That's fine: we only care about side effect on feeRate.

        // Transfer ownership of the pool to test contract (so we can call setFeeRate)
        // The factory (address(this)) mints the pool NFT to msg.sender (address(this)).
        // Since we are the owner (by default, Factory mints to deployer), we can call setFeeRate.

        // Set feeRate to 1234
        c.setFeeRate(1234);

        // Now call availableForFlashLoan with any token/ID that will NOT revert (will return false)
        // Using address(1) and tokenId 0: ownerOf(0) reverts => availableForFlashLoan returns false
        // This call should not change feeRate.
        c.availableForFlashLoan(address(1), 0);

        // Assert: feeRate should be 1234 (reference), but buggy version leaves it at 0
        assertTrue(c.feeRate() == 1234);
    }
}

