pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a mock ERC721 to mint a token to the pool
        // Using a simple inline contract
        address nft = address(new MockERC721());
        // Mint token 1 to this test contract
        MockERC721(nft).mint(address(this), 1);
        // Approve the pool to transfer
        MockERC721(nft).approve(address(c), 1);
        // Initialize the pool with baseToken = address(this) (non-zero), nft, etc.
        c.initialize(
            address(this),  // _baseToken (non-zero)
            nft,            // _nft
            1000 ether,      // _virtualBaseTokenReserves
            100 ether,       // _virtualNftReserves
            0,               // _changeFee
            0,               // _feeRate
            bytes32(0),      // _merkleRoot
            false,           // _useStolenNftOracle
            false            // _payRoyalties
        );
        // Transfer token 1 to the pool so it owns it
        MockERC721(nft).safeTransferFrom(address(this), address(c), 1);
        // Now check availableForFlashLoan
        bool ok;
        try c.availableForFlashLoan(nft, 1) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        // Reference says true (token owned by pool, initialized), bug says false (reverts because initialized is false, so calls to ownerOf revert due to uninitialized state)
        assertTrue(ok);
    }
}

contract MockERC721 {
    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;

    function mint(address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "NOT_MINTED");
        return owner;
    }

    function approve(address spender, uint256 tokenId) external {
        _tokenApprovals[tokenId] = spender;
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        require(_owners[tokenId] == from, "WRONG_FROM");
        _owners[tokenId] = to;
        _balances[from]--;
        _balances[to]++;
        delete _tokenApprovals[tokenId];
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        return _tokenApprovals[tokenId];
    }

    function isApprovedForAll(address, address) public view returns (bool) { return false; }

    function balanceOf(address owner) public view returns (uint256) {
        return _balances[owner];
    }

    function supportsInterface(bytes4) public view returns (bool) { return false; }
}

